export const getGetPollsUrl = (params?: GetPollsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/polls?${stringifiedParams}` : `/api/v1/polls`
}

/**
 * 공개(PUBLIC) 투표를 최신순으로 내린다. 마감된 투표도 closed=true로 포함하고, 각 투표의 전체 참여 수(participantCount)를 담는다. cursor는 이전 응답의 nextCursor를 그대로 넘기는 불투명한 값이다.
 * @summary 투표 목록
 */
export const getPolls = async (params?: GetPollsParams, options?: Parameters<typeof customFetch>[1]): Promise<getPollsResponse> => {

  return customFetch<getPollsResponse>(getGetPollsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





