    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createPoll>>, TError,CreatePollMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof createPoll>>,
        TError,
        CreatePollMutationVariables,
        TContext
      > => {
      return useMutation(getCreatePollMutationOptions(options), queryClient);
    }

